// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/users/{userId}/documents", wrapper.UploadDocument)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/users/{userId}/assets", wrapper.ListAssets)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/users/{userId}/assets/{assetId}", wrapper.GetAsset)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/users/{userId}/assets/{assetId}/documents", wrapper.ListAssetDocuments)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/users/{userId}/finance/accounts", wrapper.ListAccounts)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/users/{userId}/finance/accounts", wrapper.CreateAccount)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/users/{userId}/finance/accounts/{id}", wrapper.GetAccount)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/users/{userId}/finance/movements", wrapper.ListMovements)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/users/{userId}/finance/movements", wrapper.CreateMovement)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/users/{userId}/finance/movements/{id}", wrapper.DeleteMovement)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/users/{userId}/finance/movements/{id}", wrapper.GetMovement)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/users/{userId}/finance/movements/{id}", wrapper.PatchMovement)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/users/{userId}/finance/movements/{id}/link", wrapper.UnlinkMovement)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/users/{userId}/finance/movements/{id}/link", wrapper.LinkMovement)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/users/{userId}/finance/import-batches", wrapper.ListImportBatches)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/users/{userId}/finance/import-batches", wrapper.CreateImportBatch)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/users/{userId}/finance/import-batches/{id}", wrapper.GetImportBatch)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/users/{userId}/finance/import-batches/{id}/commit", wrapper.CommitImportBatch)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/users/{userId}/finance/import-batches/{id}/discard", wrapper.DiscardImportBatch)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/users/{userId}/households", wrapper.ListHouseholds)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/users/{userId}/households", wrapper.CreateHousehold)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/users/{userId}/households/{householdId}", wrapper.GetHousehold)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/users/{userId}/households/{householdId}/members", wrapper.AddHouseholdMember)
	})

	return r
}

